-	expect("a", "changed", now.Add(6*time.Minute+time.Second), false, 0)
-	if l.clear("a") != 1 {
-		t.Fatal("lost repeat count")
-	}
-	for i := 0; i < retirementLogLimit+5; i++ {
-		expect(fmt.Sprint(i), "first", now.Add(time.Duration(i)*time.Second), true, 0)
-	}
